    { id: "tickets", label: "Inbox volume", icon: <InboxIcon />, value: 2186, change: 5.4 },
    { id: "resolution", label: "Resolved today", icon: <CheckCheckIcon />, value: 312, change: 8.6 },
    { id: "sla", label: "On-time replies", icon: <Clock3Icon />, value: 94, format: { style: "percent" }, change: -0.7 },
    { id: "csat", label: "Helpfulness", icon: <ThumbsUpIcon />, value: 4.7, format: { decimals: 1 }, unit: "/ 5", change: 1.2 },
