          <dl className="art:flex art:flex-col art:gap-px art:bg-border art:@lg:w-max art:@lg:min-w-full art:@lg:flex-row">
            {metrics.map((metric, index) => {
            const positive = metric.change >= 0;
            return (<div key={metric.id} className="art:@container/metric art:flex art:min-w-0 art:flex-col art:justify-between art:bg-background art:p-4 art:@lg:flex-1 art:gap-8 art:@lg:min-w-80 art:@lg:p-5">
