                      {metric.unit ? <span className="art:font-mono art:text-base art:text-muted-foreground">{metric.unit}</span> : null}
                    </div>
                    <p className="art:flex art:flex-wrap art:items-center art:gap-x-2 art:text-sm art:text-muted-foreground">
                      <span className={`art:font-mono art:font-medium art:tabular-nums ${positive ? "art:text-success-foreground" : "art:text-destructive"}`}>
                        <RollingNumber text={formatChange(metric.change)} prefix={metric.change > 0 ? "+" : undefined} suffix="%" className="art:inline-flex art:items-baseline art:tabular-nums art:whitespace-nowrap"/>
                      </span>
                      <span>{COMPARISON_LABEL}</span>
                    </p>
                  </dd>
                </div>);
        })}
          </dl>
        </section>
      </section>
    </div>);
}

