            ? artemisCreatePortal(<MenuContent key={session} open={open} triggerId={triggerId} contentId={contentId} trigger={triggerRef.current} actions={actions} keyboardOpen={keyboardOpen} onPlacement={setPlacement} onClose={onClose} onExited={onExited}/>, document.body)
